//
// cs4231_fcode: the FCode PROM of the slot-3 audio (SUNW,CS4231), 2 KB of
// 32-bit big-endian words (byte n of the image in word n/4, lane n mod 4:
// byte 0 in bits 31:24). The word at addr is in q the cycle after (a
// synchronous ROM). Words past the 96-byte image read 0.
//
// Generated by tools/fcode_cs4231.py --sv (our own FCode, tokenized there).
// Do not edit.

module cs4231_fcode (
  input  logic        clk,
  input  logic [8:0]  addr,           // word address
  output logic [31:0] q
);

  always_ff @(posedge clk) begin
    case (addr)
      9'd0: q <= 32'hF1080D7C;
      9'd1: q <= 32'h00000060;
      9'd2: q <= 32'h120B5355;
      9'd3: q <= 32'h4E572C43;
      9'd4: q <= 32'h53343233;
      9'd5: q <= 32'h31020112;
      9'd6: q <= 32'h06736572;
      9'd7: q <= 32'h69616C01;
      9'd8: q <= 32'h1A010210;
      9'd9: q <= 32'h0C000000;
      9'd10: q <= 32'h1E010310;
      9'd11: q <= 32'h00000040;
      9'd12: q <= 32'h01161000;
      9'd13: q <= 32'h00000501;
      9'd14: q <= 32'h11120A69;
      9'd15: q <= 32'h6E746572;
      9'd16: q <= 32'h72757074;
      9'd17: q <= 32'h73011010;
      9'd18: q <= 32'h00000039;
      9'd19: q <= 32'h01111000;
      9'd20: q <= 32'h00000001;
      9'd21: q <= 32'h11011212;
      9'd22: q <= 32'h04696E74;
      9'd23: q <= 32'h72011000;
      default: q <= 32'h0;
    endcase
  end

endmodule
